// The invariant this file exists to hold: NO SHIPPED EXAMPLE LACKS ITS OWN
// PATTERN.
//
// The corpus is regenerated by a Python script that cannot run in CI (it needs
// the Tatoeba dump and fugashi/unidic-lite), so nothing stops someone re-cutting
// it on their laptop and committing the raw output. These tests are what makes
// that fail loudly: they re-run the audit against the shipped file rather than
// trusting that it was run.

import assert from "node:assert/strict";
import { describe, test } from "node:test";

import { corpus, CORPUS_META, examplesFor } from "./corpus.ts";
import type { Example } from "./corpus.ts";
import { AUDITED, auditExample, confoundFor, japaneseErrorFor } from "./corpus-audit.ts";
import droppedJson from "../generated/grammar-corpus-dropped.json" with { type: "json" };

const DROPPED = droppedJson as readonly { readonly id: number; readonly orphaned: boolean; readonly removed: boolean }[];

describe("no shipped example lacks its own pattern", () => {
  test("the audit finds nothing left to drop", () => {
    const guilty: string[] = [];
    for (const ex of corpus()) {
      for (const p of ex.p) {
        const why = confoundFor(ex, p);
        if (why) guilty.push(`${ex.id} ${ex.jp} filed as ${p}: ${why}`);
      }
    }
    assert.deepEqual(
      guilty.slice(0, 10),
      [],
      `${guilty.length} confounded examples are shipped. Run: node scripts/audit-corpus.ts`,
    );
  });

  test("the meta records that the audit ran", () => {
    // A re-cut of grammar.py writes the meta WITHOUT this block. That is the
    // signal that the audit was skipped, and it is worth more than the counts.
    assert.ok(CORPUS_META.audit, "meta has no audit block — was audit-corpus.ts skipped?");
    assert.equal(CORPUS_META.audit.rules, "src/data/grammar/corpus-audit.ts");
    assert.deepEqual([...CORPUS_META.audit.patterns].sort(), [...AUDITED].sort());
  });

  test("a sentence with no pattern is one the audit took every tag off", () => {
    // SAK-511: such a sentence stays for word examples and sentence readings.
    // It must be one the audit chose to untag, and the meta must count it.
    const struck = new Set(DROPPED.filter((d) => d.orphaned && !d.removed).map((d) => d.id));
    const untagged = corpus().filter((ex) => ex.p.length === 0);
    for (const ex of untagged) assert.ok(struck.has(ex.id), `${ex.id} has no patterns and the audit never untagged it`);
    assert.equal(CORPUS_META.audit.untaggedSentences, untagged.length);
    for (const ex of untagged) assert.deepEqual(ex.sp, {}, `${ex.id} kept a span with no pattern`);
  });

  test("no pattern's examples include a sentence with no pattern", () => {
    for (const p of Object.keys(CORPUS_META.perPattern)) {
      for (const ex of examplesFor(p)) assert.ok(ex.p.length > 0, `${ex.id} under ${p} has no patterns`);
    }
  });

  test("meta.perPattern is the file's real content, not the cap", () => {
    const actual: Record<string, number> = {};
    for (const ex of corpus()) for (const p of ex.p) actual[p] = (actual[p] ?? 0) + 1;
    for (const [p, n] of Object.entries(CORPUS_META.perPattern)) {
      assert.equal(n, actual[p] ?? 0, `meta says ${p}=${n}, the file holds ${actual[p] ?? 0}`);
    }
    assert.equal(CORPUS_META.counts.kept, corpus().length);
  });
});

describe("the sentences that made this a P0 are gone", () => {
  // Both were served live as examples of 〜ので ("because"). Neither contains
  // ので and neither is causal; the first has no other pattern, so the whole
  // sentence left, and the second survives on its `wo` claim alone.
  const knownBad = ["ログアウトするんじゃなかったよ。", "ここを動くんじゃないぞ。"];

  test("no 〜ので example is one of them", () => {
    const jp = new Set(examplesFor("node").map((e) => e.jp));
    for (const bad of knownBad) assert.ok(!jp.has(bad), `still filed under node: ${bad}`);
  });

  test("every 〜ので example contains ので", () => {
    for (const ex of examplesFor("node")) {
      assert.ok(ex.jp.includes("ので"), `${ex.id} ${ex.jp} has no ので`);
    }
  });

  test("no 〜ば example is really an obligation", () => {
    for (const ex of examplesFor("ba")) {
      const [s, e] = ex.sp["ba"]!;
      assert.ok(!ex.jp.slice(s, e).includes("なければ"), `${ex.id} ${ex.jp} is なければ`);
    }
  });
});

describe("coverage after the audit is recorded, not assumed", () => {
  /**
   * WHAT SURVIVED, PINNED.
   *
   * These are not aspirations — they are the measured post-audit counts, here
   * so that a change to the corpus or the audit rules has to state what it did
   * to teaching coverage instead of moving a number quietly. Update them
   * deliberately, with the new figure in the commit message.
   *
   * `node` is the one to watch: 214 -> 89. Still enough to drill from, but it
   * lost 58% of its supply, which is the argument for fixing the ので signature
   * in grammar.py rather than only filtering after it.
   */
  const SURVIVED: Readonly<Record<string, number>> = {
    // 257 -> 256 (SAK-501): 冷蔵庫に入れておけば肉は痛まない left for its 痛む.
    ba: 256,
    // 230 -> 140 (SAK-501): でしょ without the う, a rhetorical "right?".
    deshou: 140,
    // 213 -> 167 (SAK-501): a sentence-final からね / からな.
    "kara-reason": 167,
    // +1 over the ingest's own count — authored.ts adds one hand-picked
    // reference example (see its "particles" section) alongside the corpus.
    "made-ni": 86,
    // 324 -> 207 in the corpus (SAK-501), plus authored.ts's one row: までに
    // ("by", "ever"), 今まで + ことがある, まで as "even".
    made: 208,
    // 334 -> 2 (SAK-501): almost every ないで in the corpus is a request.
    "nai-de": 2,
    nikui: 63,
    node: 89,
    // 212 -> 164: 48 are purpose の+に ("convenient FOR doing X") or the
    // pronoun-の + choice-に of 〜にする, not concessive のに.
    noni: 164,
    // 33 -> 9 (SAK-501): らしく is the "befitting" らしい.
    rashii: 9,
    // 139 -> 137 (SAK-501): と言ったところ, "so to speak".
    "ta-tokoro": 137,
    // 425 -> 420 (SAK-501): ていろ / ていなさい, a command.
    "te-iru": 420,
    // 243 -> 234: 9 are volitional + と思う ("I intend to X"), a different
    // recipe (you-to-omou) folded into this one at ingest time.
    "to-omou": 234,
  };

  for (const [p, n] of Object.entries(SURVIVED)) {
    test(`${p} still has ${n} examples`, () => {
      assert.equal(examplesFor(p).length, n);
    });
  }

  test("no audited pattern was quietly emptied", () => {
    // The failure mode this guards is a rule that is too aggressive: an audit
    // that leaves a pattern with nothing is a pattern the app can no longer
    // teach, and that must be a decision, not a side effect.
    //
    // Two patterns are below 20 on purpose (SAK-501). In both, the tagger's
    // signature matches a different word far more often than the pattern:
    // ない + で is mostly the request "please don't", and grammar.py's rashii
    // signature reads the suffix らしい ("like a real X"), not the auxiliary
    // ("apparently"). Every sentence the rules took out was read. The fix that
    // brings the numbers back is in grammar.py, not here.
    const THIN: Readonly<Record<string, number>> = { "nai-de": 2, rashii: 9 };
    for (const p of AUDITED) {
      if (p in THIN) assert.equal(examplesFor(p).length, THIN[p], `${p} moved; read its sentences before changing this`);
      else assert.ok(examplesFor(p).length >= 20, `${p} fell to ${examplesFor(p).length}`);
    }
  });

  test("the only patterns with no examples at all are the known ones", () => {
    // ta-ato-de is genuinely scarce in Tatoeba (0 raw matches survived the
    // ingest filters); the rest are recipes deliberately given no signature.
    // Anything NEW here is a regression, whatever produced it.
    const empty = Object.entries(CORPUS_META.perPattern)
      .filter(([, n]) => n === 0)
      .map(([p]) => p)
      .sort();
    assert.deepEqual(empty, ["ta-ato-de"]);
  });
});

/** An example built the way grammar.py writes one, with the span found by
 * text. Only what confoundFor reads is filled in. */
function example(jp: string, pattern: string, span: string, en = "", id = 1): Example {
  const at = jp.indexOf(span);
  assert.ok(at >= 0, `${span} is not in ${jp}`);
  return { id, jp, en, n: 0, v: [], p: [pattern], sp: { [pattern]: [at, at + span.length, null] } };
}

describe("the SAK-501 rules drop the wrong sense and keep the right one", () => {
  const cases: ReadonlyArray<{ pattern: string; drop: readonly Example[]; keep: readonly Example[] }> = [
    {
      pattern: "nai-de",
      drop: [
        example("私にかまわないで。", "nai-de", "かまわないで", "Leave me alone, please."),
        example("窓を開けないでください。", "nai-de", "開けないで", "Please don't open the window."),
        example("食べないでいいよ。", "nai-de", "食べないで", "It's OK not to eat it."),
        example("心配しないで、楽しくいこう！", "nai-de", "しないで", "Don't worry, be happy!"),
      ],
      keep: [
        example("隠さないで話してくれ。", "nai-de", "隠さないで", "Don't hold back anything."),
        example("朝ご飯を食べないで、学校に行った。", "nai-de", "食べないで", "I went to school without eating breakfast."),
      ],
    },
    {
      pattern: "made",
      drop: [
        example("今までに本物の牛を見たことがない。", "made", "今まで", "I've never seen a real cow."),
        example("明日までにレポートを提出しなさい。", "made", "明日まで", "Hand in your report by tomorrow."),
        example("彼は今まで外国に行ったことがありません。", "made", "今まで", "He has never been abroad."),
        example("もう・・・タバコの吸殻まで散らばってるし。", "made", "吸殻まで", "Sheesh, you've even got cigarette butts scattered around."),
      ],
      keep: [
        example("翌朝まで待つしかなかった。", "made", "翌朝まで", "There was nothing to do but wait until the next morning."),
        example("今まで何してたの？", "made", "今まで", "What have you been doing all this while?"),
        example("雨でもそこまで行きます。", "made", "そこまで", "I will go there even if it rains."),
      ],
    },
    {
      pattern: "rashii",
      drop: [example("若者らしくふるまいなさい。", "rashii", "らしく", "Behave yourself like a young man.")],
      keep: [example("彼は来るらしい。", "rashii", "らしい", "Apparently he's coming.")],
    },
    {
      pattern: "ta-tokoro",
      drop: [
        example("結果は可もなく不可もなしと言ったところです。", "ta-tokoro", "言ったところ", "The result is neither good nor bad."),
        example("曲がったところに本屋がある。", "ta-tokoro", "曲がったところ", "There's a bookstore where you turn."),
      ],
      keep: [example("今帰ったところです。", "ta-tokoro", "帰ったところ", "I've just come home.")],
    },
    {
      pattern: "kara-reason",
      drop: [
        example("明日遊びに行くからね。", "kara-reason", "行くから", "I'm coming to see you tomorrow."),
        example("次壊したら、直さないからな。", "kara-reason", "ないから", "If you break it again, I'm not going to fix it."),
        example("だから言ったでしょう。", "kara-reason", "だから", "I told you so."),
      ],
      keep: [
        example("雨が降っているから、行かない。", "kara-reason", "いるから", "I'm not going because it's raining."),
        example("あなたが女の子だからよ。", "kara-reason", "だから", "It's because you're a girl."),
      ],
    },
    {
      pattern: "deshou",
      drop: [example("やめなさいって言ってるでしょ。", "deshou", "でしょ", "Stop, I say.")],
      keep: [example("明日は雨でしょう。", "deshou", "でしょう", "It will probably rain tomorrow.")],
    },
    {
      pattern: "te-iru",
      drop: [
        example("下がっていろ！", "te-iru", "下がっていろ", "Back off!"),
        example("黙っていなさい。", "te-iru", "黙ってい", "Be quiet."),
      ],
      keep: [example("疲れているんだ。", "te-iru", "疲れている", "I'm tired.")],
    },
  ];

  for (const { pattern, drop, keep } of cases) {
    test(`${pattern}: drops the other sense`, () => {
      for (const ex of drop) assert.ok(confoundFor(ex, pattern), `${ex.jp} was kept`);
    });
    test(`${pattern}: keeps the real sense`, () => {
      for (const ex of keep) assert.equal(confoundFor(ex, pattern), null, `${ex.jp} was dropped`);
    });
  }

  test("the sentence with 痛む (to hurt) for 傷む (to spoil) is gone", () => {
    const bad = example("冷蔵庫に入れておけば肉は痛まない。", "te-oku", "入れておけ", "", 77642);
    assert.ok(japaneseErrorFor(bad));
    assert.equal(japaneseErrorFor({ ...bad, id: 2 }), null);
    assert.ok(!corpus().some((ex) => ex.id === 77642), "77642 is still in the corpus");
  });
});

describe("a wrong sense takes the tag off and keeps the sentence (SAK-511)", () => {
  test("a sentence whose only pattern is confounded is kept with no tags", () => {
    const request = example("ふざけないで。", "nai-de", "ふざけないで", "Be serious.");
    const { kept, struck } = auditExample(request);
    assert.ok(kept, "the sentence left the corpus");
    assert.deepEqual(kept.p, []);
    assert.deepEqual(kept.sp, {});
    assert.deepEqual(
      struck.map((s) => s.pattern),
      ["nai-de"],
    );
  });

  test("a confound takes off only its own tag", () => {
    const ex: Example = {
      id: 1,
      jp: "窓を開けないでください。",
      en: "Please don't open the window.",
      n: 0,
      v: [],
      p: ["wo", "nai-de"],
      sp: { wo: [1, 2, null], "nai-de": [2, 7, null] },
    };
    const { kept } = auditExample(ex);
    assert.deepEqual(kept?.p, ["wo"]);
    assert.deepEqual(Object.keys(kept?.sp ?? {}), ["wo"]);
  });

  test("a sentence with no confound comes back as it was", () => {
    const ex = example("疲れているんだ。", "te-iru", "疲れている", "I'm tired.");
    assert.equal(auditExample(ex).kept, ex);
  });

  test("wrong Japanese takes the whole sentence out", () => {
    const bad = example("冷蔵庫に入れておけば肉は痛まない。", "te-oku", "入れておけ", "", 77642);
    const { kept, struck } = auditExample(bad);
    assert.equal(kept, null);
    assert.deepEqual(
      struck.map((s) => s.pattern),
      ["te-oku"],
    );
  });

  test("the ないで requests SAK-501 untagged are word examples again", () => {
    const ex = corpus().find((e) => e.jp === "ふざけないで。");
    assert.ok(ex, "ふざけないで。 left the corpus");
    assert.deepEqual(ex.p, []);
  });
});
